export class Effects { constructor() { this.flashTime = 0; this.kind = ''; } flash(kind) { this.kind = kind; this.flashTime = .12; } update(dt) { this.flashTime = Math.max(0, this.flashTime - dt); } draw(ctx, canvas) { if (this.flashTime <= 0) return; ctx.strokeStyle = this.kind === 'hit' ? '#fff4db' : '#9df5ae'; ctx.lineWidth = 2; ctx.strokeRect(canvas.width / 2 - 12, canvas.height / 2 - 12, 24, 24); } }